verify.cmd:
node --experimental-strip-types --no-warnings --import ./scripts/probe-ts.mjs -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const vf=rd("lib/engagement/verify.ts")
if(vf===null)process.exit(79)
if(!/nodeCodeVerdict\(/.test(vf)||!/===\s*[\x27"]refused[\x27"]\)\s*return\s*\{\s*ok:\s*false,\s*reason:\s*[\x27"]bad_signature/.test(vf))fail("the capture verifier does not refuse a code that fails the signed-code check, so a forged /n/<id> checks a member in (LIVE-688)")
if(/presentedSecret\s*!==\s*node\.secret/.test(vf))fail("the verifier still compares a stored plain secret as the gate")
const surfaces=["app/(main)/admin/qr/page.tsx","app/api/qr/route.ts","app/print/qr/page.tsx","app/(main)/spaces/[slug]/settings/checkin/section.tsx"]
for(const f of surfaces){const s=rd(f);if(s===null)process.exit(79);if(!/signedNodeUrl\(/.test(s)||/nodeUrl\([^)]*\.secret\)/.test(s))fail(f+" renders a node code that is not signed, so a printed code can be forged from its node id")}
process.env.UNSUBSCRIBE_SECRET="probe-node-code-key-000000000000000000"
import("@/lib/qr/node-code.ts").then((m)=>{
const A="11111111-1111-4111-8111-111111111111",B="22222222-2222-4222-8222-222222222222"
const t=Date.parse("2026-09-29T12:00:00Z"),after=m.LEGACY_NODE_CODE_GRACE_ENDS+1,before=m.LEGACY_NODE_CODE_GRACE_ENDS-1
const code=m.signNodeCode(A,t)
if(!(after<Date.parse("2026-12-21T00:00:00Z")))fail("the grace window for printed codes runs past launch day")
const v=(p,sec,now)=>m.nodeCodeVerdict({nodeId:A,presented:p,legacySecret:sec,now})
if(v(code,null,after)!=="signed")fail("a code this server signed for the node does not verify")
if(v(m.signNodeCode(B,t),null,before)!=="refused")fail("a code signed for another node checks a member in")
const tampered=code.slice(0,-1)+(code.endsWith("A")?"B":"A")
if(v(tampered,"old-secret",before)!=="refused")fail("a tampered code checks a member in inside the grace window")
const parts=code.split(".")
if(v(parts[0]+"."+(parseInt(parts[1],36)+1).toString(36)+"."+parts[2],null,after)!=="refused")fail("a code with an edited issue time verifies")
if(v(null,null,after)!=="refused")fail("after the grace window a bare /n/<id> with no code still checks a member in")
if(v("old-secret","old-secret",after)!=="refused")fail("after the grace window the old stored secret still checks a member in")
if(v(null,null,before)!=="legacy"||v("old-secret","old-secret",before)!=="legacy")fail("codes printed before signing stop working before the grace window ends")
const u=new URL(m.signedNodeUrl(A,t))
if(u.pathname!=="/n/"+A||v(u.searchParams.get("s"),null,after)!=="signed")fail("the printed URL does not carry a code that verifies")
console.log("ok")
}).catch((e)=>fail("cannot run lib/qr/node-code.ts: "+(e&&e.message)))'
